}

ListNode fromArray(int[] values) {
    ListNode dummy = new ListNode(0);   // placeholder in front of the head
    ListNode tail = dummy;
    for (int v : values) {
        tail.next = new ListNode(v);    // attach a new node at the end
        tail = tail.next;
    }
    return dummy.next;                  // the real head
}

ListNode* fromArray(const vector<int>& values) {
    ListNode dummy(0);         // placeholder in front of the head
    ListNode* tail = &dummy;
    for (int v : values) {
        tail->next = new ListNode(v);   // attach a new node at the end
        tail = tail->next;
    }
    return dummy.next;         // the real head
}

function length(head) {
  let count = 0;
  for (let curr = head; curr !== null; curr = curr.next) count++;
  return count;
}

int length(ListNode head) {
    int count = 0;
    for (ListNode curr = head; curr != null; curr = curr.next) count++;
    return count;
}

int length(ListNode* head) {
    int count = 0;
    for (ListNode* curr = head; curr != nullptr; curr = curr->next) count++;
    return count;
}

function insertAt(head, pos, x) {
  const node = new ListNode(x);
  if (pos === 0) {           // new head
    node.next = head;
    return node;
  }
  let prev = head;
  for (let i = 0; i < pos - 1; i++) prev = prev.next;   // node before the spot
  node.next = prev.next;     // 1. hold on to the rest
  prev.next = node;          // 2. hook the new node in
  return head;
}

ListNode insertAt(ListNode head, int pos, int x) {
