function deleteValue(head, x) {
  if (head === null) return null;
  if (head.val === x) return head.next;     // deleting the head
  let prev = head;
  while (prev.next !== null && prev.next.val !== x) prev = prev.next;
  if (prev.next !== null) prev.next = prev.next.next;   // skip over it
  return head;
}

def delete_value(head, x):
    if head is None:
        return None
    if head.val == x:              # deleting the head
        return head.next
    prev = head
    while prev.next is not None and prev.next.val != x:
        prev = prev.next
    if prev.next is not None:
        prev.next = prev.next.next # skip over it
    return head

ListNode deleteValue(ListNode head, int x) {
    if (head == null) return null;
    if (head.val == x) return head.next;      // deleting the head
    ListNode prev = head;
    while (prev.next != null && prev.next.val != x) prev = prev.next;
    if (prev.next != null) prev.next = prev.next.next;   // skip over it
    return head;
}

ListNode* deleteValue(ListNode* head, int x) {
    if (head == nullptr) return nullptr;
    if (head->val == x) return head->next;    // deleting the head
    ListNode* prev = head;
    while (prev->next != nullptr && prev->next->val != x) prev = prev->next;
    if (prev->next != nullptr) prev->next = prev->next->next;   // skip over it
    return head;
}
